// known.js - the houses the research dossiers describe (docs/research/west-nevsky-{1,2,3}-houses.json), looked up by OSM id.
//   known-data.js   GENERATED by tools/city-known.mjs (149 ids: archetype, storeys, cornice height, facade / trim / roof colours, mansard, erkers)
//   known-extra.js  hand corrections (keyed by OSM id), merged over the generated entry
// A part inherits the entry of its parent outline (`b.parent`); a synthesised base (`<part>~f`, prep.js) the entry of the part it stands under.
// knownFor(b) -> normalised spec { arch, floors, H, hex, trim (class 0-6, wallmat.trimFlags), roofHex, mansard (true / false / undefined), erkers, rust, shop, rich, gfTint, wear, turret, name,
//   gables, gableShape, majolica, socle, parapet, columns, turretTop (Petrograd-side grammar) } or undefined.
import { ARCH } from './wallmat.js';
import { KNOWN_DATA } from './known-data.js';
import { KNOWN_EXTRA } from './known-extra.js';

const cache = new Map();
function norm(e) {
  const o = { name: e.n };
  if (e.a && ARCH[e.a] !== undefined) o.arch = ARCH[e.a];
  if (e.f) o.floors = e.f;
  if (e.H) o.H = e.H;
  if (e.hex) o.hex = e.hex;
  if (e.tr) o.trim = e.tr;
  if (e.rf) o.roofHex = e.rf;
  if (e.ms !== undefined) o.mansard = !!e.ms;
  if (e.er !== undefined) o.erkers = !!e.er;
  if (e.rust) o.rust = true;
  if (e.tu !== undefined) o.turret = !!e.tu;
  if (e.ga) o.gate = e.ga;
  for (const k of ['shop', 'rich', 'gfTint', 'wear', 'turret', 'balconies', 'passage', 'granite', 'custom']) if (e[k] !== undefined) o[k] = e[k];
  // Petrograd-side grammar (tools/city-known-petro.mjs): gb gables per street front, yard 1 = stands free in a yard (all walls are fronts), gs gable shape 0-3, mj majolica band, so rough stepped granite socle, pp parapet 'bal' / 'attic' / 0, col half-columns, tt turret top
  if (e.gb !== undefined) o.gables = e.gb;
  if (e.gs !== undefined) o.gableShape = e.gs;
  if (e.mj !== undefined) o.majolica = !!e.mj;
  if (e.so !== undefined) o.socle = !!e.so;
  if (e.pp !== undefined) o.parapet = e.pp || null;
  if (e.col !== undefined) o.columns = !!e.col;
  if (e.tt) o.turretTop = e.tt;
  if (e.yard) o.allFronts = true;
  return o;
}
function lookup(id) {
  if (cache.has(id)) return cache.get(id);
  const d = KNOWN_DATA[id], x = KNOWN_EXTRA[id];
  const r = d || x ? norm({ ...(d || {}), ...(x || {}) }) : undefined;
  cache.set(id, r);
  return r;
}
/** The spec of a building / part record, or undefined. Own id first (an extra entry for a part wins), then the parent outline. */
export function knownFor(b) {
  const id = b._fillOf || b.id;
  return lookup(id) || (b.parent ? lookup(b.parent) : undefined);
}
export const knownIds = () => new Set([...Object.keys(KNOWN_DATA), ...Object.keys(KNOWN_EXTRA)]);
